// Slack signs every request: HMAC-SHA256 over "v0:<timestamp>:<raw body>"
// with the app's signing secret. This node checks the timestamp and builds
// that string from the exact raw bytes; the next node (Crypto) signs it with
// the secret held in an n8n credential.
// https://api.slack.com/authentication/verifying-requests-from-slack
const MAX_AGE_SECONDS = 300; // Slack's recommended replay window

const { headers, body } = $input.first().json;
const timestamp = String(headers['x-slack-request-timestamp'] ?? '');
if (!/^\d+$/.test(timestamp) || Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_AGE_SECONDS) {
  throw new Error('Rejected: missing or stale Slack timestamp (possible replay)');
}
// Raw body as received (Webhook option "Raw Body"); re-encoding the parsed
// form would not reproduce Slack's bytes exactly.
const rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');

return [{
  json: {
    base_string: `v0:${timestamp}:${rawBody}`,
    signature: String(headers['x-slack-signature'] ?? ''),
    payload: String(body?.payload ?? ''),
  },
}];

// Accept the click only if Slack's signature matches. Slack can't send a
// custom auth header, so without this check anyone who learns the webhook URL
// could post fake clicks and write attack strings into the training data as
// "safe", teaching the model to let them through.
// Slack user IDs allowed to flag false positives, e.g. ['U012ABCDEF'];
// empty = anyone who can see the alert channel.
const ALLOWED_USER_IDS = [];

const item = $input.first().json;
const expected = `v0=${item.expected_signature}`;
const given = item.signature;
// Constant-time comparison (require('crypto') is disallowed in Code nodes).
let diff = expected.length ^ given.length;
for (let i = 0; i < expected.length; i++) {
  diff |= expected.charCodeAt(i) ^ (given.charCodeAt(i) || 0);
}
if (diff !== 0) {
  throw new Error('Rejected: invalid Slack signature');
}

const payload = JSON.parse(item.payload || '{}');
const action = (payload.actions ?? []).find((a) => String(a.action_id ?? '').startsWith('waf_fp_'));
if (payload.type !== 'block_actions' || !action) {
  return []; // some other interaction: nothing to do
}
const user = payload.user ?? {};
if (ALLOWED_USER_IDS.length && !ALLOWED_USER_IDS.includes(user.id)) {
  throw new Error(`Rejected: Slack user ${user.id} is not allowed to flag false positives`);
}
const value = JSON.parse(action.value ?? '{}');
if (typeof value.q !== 'string' || !value.q.trim()) {
  throw new Error('Rejected: the button carries no value');
}
// The update is only ever posted back to Slack.
if (!/^https:\/\/hooks\.slack\.com\//.test(payload.response_url ?? '')) {
  throw new Error('Rejected: unexpected response_url');
}

return [{
  json: {
    query: value.q,
    label: 0,
    source: String(value.s ?? '').slice(0, 100),
    request_id: String(value.r ?? '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64),
    flagged_by: `${user.username ?? user.name ?? 'unknown'} (${user.id ?? '?'})`.slice(0, 100),
    user_id: user.id,
    action_id: action.action_id,
    response_url: payload.response_url,
    message: payload.message ?? {},
  },
}];

// Rebuild the alert: drop the clicked button, record who flagged the value,
// and turn the colour bar green. If the ML API did not record it, say so and
// keep the button so the click can be retried.
const flag = $('Verify & parse click').first().json;
const res = $input.first().json; // full HTTP response: statusCode, body (or error)
const recorded = res.statusCode === 201;
const duplicate = recorded && res.body?.status === 'duplicate';

const esc = (value, max = 100) => String(value ?? '')
  .slice(0, max)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const message = flag.message ?? {};
const attachment = message.attachments?.[0] ?? {};
const blocks = (attachment.blocks ?? message.blocks ?? []).map((block) => {
  if (recorded && block.accessory?.action_id === flag.action_id) {
    const { accessory, ...rest } = block;
    return rest;
  }
  return block;
});

const note = recorded
  ? `:white_check_mark: Flagged as False Positive by <@${flag.user_id}>: the *${esc(flag.source)}* value ${duplicate ? 'was already in' : 'was added to'} the training data as safe.`
  : `:x: <@${flag.user_id}> tried to flag the *${esc(flag.source)}* value as a false positive, but the ML API ${res.statusCode ? `answered HTTP ${res.statusCode}` : 'could not be reached'}. Not recorded; try again.`;
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: note }] });

const color = recorded ? '#2eb886' : `#${String(attachment.color ?? 'd40e0d').replace(/^#/, '')}`;
return [{
  json: {
    response_url: flag.response_url,
    update: {
      replace_original: true,
      text: message.text ?? 'SQL injection alert',
      attachments: [{ color, blocks }],
    },
  },
}];
